 ("u1_uvp", r"\begin{aligned}u&=[0.1875(1)+0.0625(2)+0.1875(3)+0.5625(1)]\times10^{-5}=1.4375\times10^{-5}\ \mathrm{m}\\v&=[0.1875(0.1)+0.0625(0.1)+0+0]\times10^{-5}=2.5\times10^{-7}\ \mathrm{m}\end{aligned}"),
 ("u1_epsp", r"\begin{aligned}\varepsilon_{xx}&=\frac{0.1(2-1)+0.3(3-1)}{0.24}\times10^{-5}=2.9167\times10^{-5}\\[4pt]\varepsilon_{yy}&=\frac{0.45(0-0.1)+0.15(0-0.1)}{0.24}\times10^{-5}=-2.5\times10^{-6}\\[4pt]\varepsilon_{xy}&=\frac{0.45(1-1)+0.15(3-2)}{0.24}\times10^{-5}+\frac{0.1(0.1-0.1)+0.3(0-0)}{0.24}\times10^{-5}=6.25\times10^{-6}\end{aligned}"),
 ("u1_sigp", r"\begin{Bmatrix}\sigma_{xx}\\\sigma_{yy}\\\sigma_{xy}\end{Bmatrix}=219.78\times10^{6}\begin{Bmatrix}2.9167\times10^{-5}-0.3(2.5\times10^{-6})\\0.3(2.9167\times10^{-5})-2.5\times10^{-6}\\0.35\,(6.25\times10^{-6})\end{Bmatrix}=\begin{Bmatrix}6245\\1374\\481\end{Bmatrix}\ \mathrm{kN/m^2}"),
 ("u1_centre_c", r"\begin{aligned}\text{centre, }u_3=3\times10^{-5}:\quad&\varepsilon=\{2.5\times10^{-5},\ -2.5\times10^{-6},\ 1.25\times10^{-5}\}\\&\sigma=\{5330,\ 1099,\ 962\}\ \mathrm{kN/m^2}\end{aligned}"),
 # ---- Example 2: [E] for plane stress and plane strain (book Practice Problem 9.1, extended) ----
 ("u2_ps", r"\begin{aligned}\frac{E}{1-\nu^2}&=\frac{30\times10^{6}}{1-0.04}=31.25\times10^{6}\\\nu\,\frac{E}{1-\nu^2}&=6.25\times10^{6},\qquad\frac{1-\nu}{2}\,\frac{E}{1-\nu^2}=12.5\times10^{6}\\[4pt][E]_{\sigma}&=\begin{bmatrix}31.25&6.25&0\\6.25&31.25&0\\0&0&12.5\end{bmatrix}\times10^{6}\ \mathrm{kN/m^2}\end{aligned}"),
