 ("u2_zz", r"\begin{aligned}\text{plane stress: }&\sigma_{zz}=0,\qquad\varepsilon_{zz}=-\frac{\nu}{E}(\sigma_{xx}+\sigma_{yy})=-\frac{0.2(7500)}{30\times10^{6}}=-5.0\times10^{-5}\\\text{plane strain: }&\varepsilon_{zz}=0,\qquad\sigma_{zz}=\nu(\sigma_{xx}+\sigma_{yy})=0.2(6667+1667)=1667\ \mathrm{kN/m^2}\end{aligned}"),
