 ("u3_loads", r"\begin{aligned}r_7&=\frac{qh}{2},\quad r_{15}=\frac{qh}{2}+\frac{qh}{2}=qh,\quad r_{23}=qh,\quad r_{31}=\frac{qh}{2}\\[2pt]\textstyle\sum r&=3qh=q\times\text{height}\qquad(\text{all other entries of }\{r\}\text{ zero})\end{aligned}"),
 ("u3_rigid", r"\begin{aligned}u&=-\theta y,\quad v=\theta x:\qquad\varepsilon_{xx}=\frac{\partial u}{\partial x}=0,\quad\varepsilon_{yy}=\frac{\partial v}{\partial y}=0,\quad\varepsilon_{xy}=\frac{\partial u}{\partial y}+\frac{\partial v}{\partial x}=-\theta+\theta=0\end{aligned}"),
